use std::collections::HashSet;

fn has_common_element(a: &Vec<i32>, b: &Vec<i32>) -> bool {
    // To improve efficiency, insert elements of the smaller vector into a HashSet,
    // then check for any element in the larger vector that exists in the set.

    if a.len() < b.len() {
        let set: HashSet<_> = a.iter().cloned().collect();
        b.iter().any(|&val| set.contains(&val))
    } else {
        let set: HashSet<_> = b.iter().cloned().collect();
        a.iter().any(|&val| set.contains(&val))
    }
}